import socket,ssl,struct,time,ipaddress
def execute(host,port,tls_name,ca_file,query):
    if not ipaddress.ip_address(host).is_loopback:raise ValueError('numeric loopback only')
    if type(port) is not int or not 1024<=port<=65535:raise ValueError('high port required')
    if not isinstance(query,bytes) or not 12<=len(query)<=65535 or query[2]&0x80:raise ValueError('DNS query bytes required')
    context=ssl.create_default_context(cafile=ca_file)
    deadline=time.monotonic()+1
    def remaining():
        left=deadline-time.monotonic()
        if left<=0:raise TimeoutError('DoT total deadline')
        return left
    with socket.create_connection((host,port),timeout=remaining()) as raw:
        raw.settimeout(remaining())
        with context.wrap_socket(raw,server_hostname=tls_name) as conn:
            conn.settimeout(remaining());conn.sendall(struct.pack('!H',len(query))+query)
            def read(size):
                result=b''
                while len(result)<size:
                    conn.settimeout(remaining());chunk=conn.recv(size-len(result))
                    if not chunk:raise EOFError('truncated DoT frame')
                    result+=chunk
                return result
            size=struct.unpack('!H',read(2))[0]
            if size<12:raise ValueError('short DNS message')
            response=read(size)
            if response[:2]!=query[:2] or not response[2]&0x80 or response[2]&2:raise ValueError('DNS ID/QR/TC mismatch')
            remaining();return response
