@contextlib.contextmanager
def server(query,response,mode='normal',untrusted=False):
    listener=socket.socket();listener.bind(('127.0.0.1',0));listener.listen(1);listener.settimeout(2)
    stop=threading.Event();errors=[];received=[];connections=[]
    def worker():
        try:
            raw,_=listener.accept();connections.append(raw);raw.settimeout(2)
            with raw:
                try:secure=context.wrap_socket(raw,server_side=True)
                except ssl.SSLError:
                    if untrusted:return
                    raise
                connections.append(secure)
                with secure:
                    count=struct.unpack('!H',read(secure,2))[0];payload=read(secure,count);received.append(payload);assert payload==query
                    wire=struct.pack('!H',len(response))+response
                    if mode=='short':wire=wire[:-1]
                    chunks=[wire[:1],wire[1:3],wire[3:]] if mode!='slow' else [wire[i:i+2] for i in range(0,len(wire),2)]
                    for part in chunks:
                        if stop.wait(.21 if mode=='slow' else .01):break
                        try:secure.sendall(part)
                        except (BrokenPipeError,ConnectionResetError,ssl.SSLError):break
        except OSError as exc:
            if not stop.is_set():errors.append(repr(exc))
        except Exception as exc:errors.append(repr(exc))
        finally:listener.close()
    thread=threading.Thread(target=worker);thread.start()
    try:yield listener.getsockname()[1],received
    finally:
        stop.set();listener.close()
        for c in connections:
            try:c.shutdown(socket.SHUT_RDWR)
            except OSError:pass
